{
  "passages": [
    {
      "id": "c1",
      "about_topic": true,
      "says": "rule: must stop when approaching a stopped school bus with upper alternating red lights flashing, from either direction (passing is prohibited); penalty from c5 attached"
    },
    {
      "id": "c2",
      "about_topic": true,
      "says": "rule: when coming from behind the bus, stop at least 20 m from the bus"
    },
    {
      "id": "c3",
      "about_topic": true,
      "says": "rule: do not go (pass) until the bus moves or the lights stop flashing"
    },
    {
      "id": "c4",
      "about_topic": true,
      "says": "exception: with a median strip, only vehicles from behind the bus must stop (front-approaching vehicles are exempt)"
    },
    {
      "id": "m77",
      "about_topic": true,
      "says": "fact: school bus drivers and other witnesses can report vehicles that have illegally passed a school bus"
    },
    {
      "id": "c5",
      "about_topic": true,
      "says": "penalty for not stopping (illegally passing) a school bus: heavy fine and 6 demerit points for a first offence"
    },
    {
      "id": "m16",
      "about_topic": true,
      "says": "rule: must not pass any vehicle within 30 m of a pedestrian crossover"
    }
  ],
  "statements": [
    {
      "id": "s1",
      "type": "RULE",
      "force": "LEGAL",
      "force_from": "text (\"must stop\")",
      "text": "a driver MUST stop WHEN the driver approaches a stopped school bus with its upper alternating red lights flashing from behind OR from the front IF VIOLATED a heavy fine AND 6 demerit points for a first offence",
      "sources": [
        {
          "id": "c1",
          "quote": "You must stop whenever you approach a stopped school bus with its upper alternating red lights flashing, regardless of whether you are behind the bus or approaching it from the front."
        },
        {
          "id": "c5",
          "quote": "If you don't stop, you can be fined heavily and get six demerit points for a first offence."
        }
      ],
      "flags": [
        {
          "code": "J",
          "span": "heavy",
          "note": "No fine amount is given; \"heavily\" leaves the size of the fine to judgment."
        }
      ],
      "links": [],
      "note": "The penalty from c5 is attached to this main stop rule. \"regardless of whether\" is written as \"from behind OR from the front\"."
    },
    {
      "id": "s2",
      "type": "RULE",
      "force": "LEGAL",
      "force_from": "context (c1: \"You must stop\"; c2 specifies the stopping distance for that duty)",
      "text": "a driver MUST stop at least 20 m from the bus WHEN the driver approaches a stopped school bus with its upper alternating red lights flashing from behind",
      "sources": [
        {
          "id": "c1",
          "quote": "You must stop whenever you approach a stopped school bus with its upper alternating red lights flashing, regardless of whether you are behind the bus or approaching it from the front."
        },
        {
          "id": "c2",
          "quote": "If you are coming from behind the bus, stop at least 20 metres away."
        }
      ],
      "flags": [],
      "links": [],
      "note": "The 20 m distance applies specifically to the from-behind approach. The general condition (stopped school bus, red lights) comes from c1."
    },
    {
      "id": "s3",
      "type": "RULE",
      "force": "LEGAL",
      "force_from": "context (c1: \"You must stop\"; c3's \"Do not go\" is the continuation of that stop)",
      "text": "a driver MUST NOT pass the school bus WHEN the school bus is stopped with its upper alternating red lights flashing UNTIL the bus moves OR the lights stop flashing",
      "sources": [
        {
          "id": "c1",
          "quote": "You must stop whenever you approach a stopped school bus with its upper alternating red lights flashing, regardless of whether you are behind the bus or approaching it from the front."
        },
        {
          "id": "c3",
          "quote": "Do not go until the bus moves or the lights have stopped flashing."
        }
      ],
      "flags": [],
      "links": [],
      "note": "The handbook says \"Do not go\"; written as \"pass the school bus\" because the prohibition in context is against passing the bus."
    },
    {
      "id": "s4",
      "type": "EXCEPTION",
      "force": null,
      "force_from": null,
      "text": "EXCEPTION TO s1 WHEN the road has a median strip AND the driver is approaching the bus from the front",
      "sources": [
        {
          "id": "c4",
          "quote": "If you are on a road with a median strip, only vehicles coming from behind the bus must stop."
        }
      ],
      "flags": [],
      "links": [
        "s1"
      ],
      "note": "With a median strip, s1's \"from behind OR from the front\" no longer applies to front-approaching vehicles; they are not required to stop and may pass."
    },
    {
      "id": "s5",
      "type": "FACT",
      "force": null,
      "force_from": null,
      "text": "FACT in Ontario, school bus drivers and other witnesses can report vehicles that have illegally passed a school bus",
      "sources": [
        {
          "id": "m77",
          "quote": "In Ontario, school bus drivers and other witnesses can report vehicles that have illegally passed a school bus."
        }
      ],
      "flags": [],
