      "force_from": "text (\"must not\")",
      "text": "a driver MUST NOT pass any vehicle WHEN the driver is within 30 m of a pedestrian crossover",
      "sources": [
        {
          "id": "m16",
          "quote": "You must not pass any vehicle within 30 metres of a pedestrian crossover."
        }
      ],
